(() => {
  const $ = (selector, root = document) => root.querySelector(selector);
  const syncPlatformNavigation = () => {
    const section = location.hash || '#overview';
    document.querySelectorAll('.platform-sidebar .portal-nav a').forEach((link) => {
      const active = (new URL(link.href, location.origin).hash || '#overview') === section;
      link.classList.toggle('active', active);
      if (active) link.setAttribute('aria-current', 'location');
      else link.removeAttribute('aria-current');
    });
  };
  window.addEventListener('hashchange', syncPlatformNavigation);
  syncPlatformNavigation();
  const state = { companies: [], loadError: null, health: 'checking' };
  const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
  const api = async (url, options = {}) => { const response = await fetch(url, { credentials: 'same-origin', headers: { 'Content-Type': 'application/json', ...(options.headers || {}) }, ...options }); const payload = await response.json().catch(() => ({})); if (response.status === 401) { location.href = '/login?next=/platform'; throw new Error('Требуется войти в систему.'); } if (response.status === 403) throw new Error('Доступ только владельцу SaaS.'); if (!response.ok) throw new Error(payload.error || `HTTP ${response.status}`); return payload; };
  const planLabel = (value) => ({ starter: 'Starter', growth: 'Growth', network: 'Network', enterprise: 'Enterprise' }[value] || value || 'Starter');
  const statusLabel = (item) => ({ trialing: 'Пробный период', active: 'Активна', past_due: 'Требует внимания', cancelled: 'Приостановлена' }[item.status] || (item.isActive === false ? 'Приостановлена' : 'Активна'));
  const renderPlans = (payload) => { const plans = payload.plans || {}; $('#plan-cards').innerHTML = Object.entries(plans).map(([key, plan]) => `<article class="plan-card"><div class="plan-card-top"><b>${escapeHtml(plan.name || planLabel(key))}</b><span>${Number(plan.monthlyPrice || 0)} ₽/мес</span></div><p>${escapeHtml(plan.description || '')}</p><div class="plan-limits"><span>${plan.seatsLimit >= 9999 ? 'Безлимит' : Number(plan.seatsLimit)} мест</span><span>${plan.venuesLimit >= 9999 ? 'Безлимит' : Number(plan.venuesLimit)} завед.</span></div></article>`).join(''); };
  const renderKpis = (overview) => { $('#platform-kpis').innerHTML = `<article><span>Всего компаний</span><strong>${Number(overview.companies) || 0}</strong><small>в реестре платформы</small></article><article><span>Активные</span><strong>${Number(overview.activeCompanies) || 0}</strong><small>по данным сервера</small></article><article><span>Пробный период</span><strong>${Number(overview.trials) || 0}</strong><small>в пробном периоде</small></article><article><span>Состояние</span><strong class="${state.health === 'ok' ? 'good-text' : 'bad-text'}">${state.health === 'ok' ? 'Доступен' : 'Нет связи'}</strong><small>проверка API</small></article>`; };
  const renderHealth = () => { const healthy = state.health === 'ok'; $('.platform-header .live-dot').textContent = healthy ? '● API доступен' : '● API недоступен'; $('.platform-header .live-dot').classList.toggle('offline', !healthy); const healthCard = $('#health'); healthCard.querySelector('.status-dot').classList.toggle('good', healthy); healthCard.querySelector('b').textContent = healthy ? 'Сервис CRM и API доступны' : 'Нет подтверждения доступности CRM и API'; healthCard.querySelector('p').textContent = healthy ? 'Проверка API прошла успешно. Изоляция организаций задаётся серверной сессией.' : 'Не удалось подтвердить доступность. Повторите проверку после восстановления соединения.'; };
  const renderCompanies = () => { const query = String($('#company-search').value || '').trim().toLowerCase(); const items = state.companies.filter((item) => `${item.name} ${item.city} ${item.slug}`.toLowerCase().includes(query)); $('#companies-body').innerHTML = items.map((item) => { const label = statusLabel(item); const active = item.status ? item.status === 'active' || item.status === 'trialing' : item.isActive !== false; return `<tr><td><div class="company-name"><span class="company-avatar">${escapeHtml((item.name || 'C').slice(0, 1))}</span><div><b>${escapeHtml(item.name)}</b><small>${escapeHtml(item.slug)}</small></div></div></td><td>${escapeHtml(item.city || '—')}</td><td><select class="plan-select" data-org-plan="${escapeHtml(item.id)}" aria-label="Тариф ${escapeHtml(item.name)}"><option value="starter" ${item.plan === 'starter' ? 'selected' : ''}>Starter</option><option value="growth" ${item.plan === 'growth' ? 'selected' : ''}>Growth</option><option value="network" ${item.plan === 'network' ? 'selected' : ''}>Network</option><option value="enterprise" ${item.plan === 'enterprise' ? 'selected' : ''}>Enterprise</option></select></td><td>${Number(item.venues) || 0}</td><td>${Number(item.seats) || 0}</td><td><span class="state-pill ${active ? 'active' : 'paused'}">${escapeHtml(label)}</span></td><td><button class="table-action" data-org-id="${escapeHtml(item.id)}" type="button">Открыть</button></td></tr>`; }).join('') || `<tr><td colspan="7" class="empty-state">${state.loadError ? escapeHtml(state.loadError) : query ? 'Компании не найдены' : 'Компаний пока нет'}</td></tr>`; };
  const load = async () => { const table = $('#companies-body'); table.innerHTML = '<tr><td colspan="7" class="empty-state">Загрузка компаний…</td></tr>'; state.loadError = null; try { const [overview, companies, plans, health] = await Promise.all([api('/api/platform/overview'), api('/api/platform/organizations'), api('/api/platform/plans'), api('/api/health')]); state.health = health.status === 'ok' ? 'ok' : 'down'; renderKpis(overview); renderPlans(plans); renderHealth(); state.companies = companies.items || []; renderCompanies(); $('#platform-updated').textContent = `Проверено ${new Intl.DateTimeFormat('ru-RU', { hour: '2-digit', minute: '2-digit' }).format(new Date())}`; } catch (error) { state.loadError = `Не удалось загрузить данные: ${error.message}`; state.health = 'down'; renderHealth(); table.innerHTML = `<tr><td colspan="7" class="empty-state">${escapeHtml(state.loadError)} <button class="table-action" type="button" data-retry-load>Повторить</button></td></tr>`; $('#platform-kpis').innerHTML = '<article><span>Состояние</span><strong class="bad-text">Недоступно</strong><small>ошибка загрузки</small></article>'; $('#platform-updated').textContent = 'Проверка не удалась'; } };
  const modal = $('#company-modal'); const detailModal = $('#company-detail-modal'); let detailOrgId = null; let detailLoaded = false; let detailTrigger = null; let createTrigger = null;
  const toggleModal = (open) => { modal.hidden = !open; if (open) { createTrigger = document.activeElement; modal.querySelector('input[name=name]').focus(); } else createTrigger?.focus(); };
  const toggleDetail = (open) => { detailModal.hidden = !open; if (open) $('#company-detail-plan').focus(); else { detailOrgId = null; detailLoaded = false; $('#save-company-detail').disabled = true; detailTrigger?.focus(); } };
  const setBusy = (button, busy, label) => { if (!button.dataset.idleLabel) button.dataset.idleLabel = button.textContent.trim(); button.disabled = busy; button.textContent = busy ? label : button.dataset.idleLabel; };
  $('#open-company').addEventListener('click', () => toggleModal(true)); $('#close-company').addEventListener('click', () => toggleModal(false)); $('#cancel-company').addEventListener('click', () => toggleModal(false)); $('#company-search').addEventListener('input', renderCompanies);
  $('#companies-body').addEventListener('click', async (event) => {
    if (event.target.closest('[data-retry-load]')) { load(); return; }
    const button = event.target.closest('[data-org-id]'); if (!button) return;
    detailTrigger = button; detailOrgId = button.dataset.orgId; detailLoaded = false; $('#save-company-detail').disabled = true;
    const item = state.companies.find((entry) => entry.id === detailOrgId); if (!item) return;
    $('#company-detail-title').textContent = item.name; $('#company-detail-meta').textContent = `${item.city || 'Город не указан'} · ${item.venues || 0} заведений · ${item.seats || 0} сотрудников`;
    $('#company-detail-error').textContent = 'Загрузка подписки…'; $('#company-detail-plan').value = item.plan || 'starter'; $('#company-detail-status').value = item.status || (item.isActive === false ? 'cancelled' : 'trialing'); toggleDetail(true);
    try { const subscription = await api(`/api/platform/organizations/${encodeURIComponent(detailOrgId)}/subscription`); if (detailOrgId !== button.dataset.orgId) return; $('#company-detail-plan').value = subscription.plan || $('#company-detail-plan').value; $('#company-detail-status').value = subscription.status || $('#company-detail-status').value; $('#company-detail-error').textContent = ''; detailLoaded = true; $('#save-company-detail').disabled = false; } catch (error) { $('#company-detail-error').textContent = `Не удалось загрузить подписку: ${error.message}`; }
  });
  $('#companies-body').addEventListener('change', async (event) => { const select = event.target.closest('[data-org-plan]'); if (!select) return; const item = state.companies.find((entry) => entry.id === select.dataset.orgPlan); if (!item) return; const previous = item.plan; select.disabled = true; try { await api(`/api/platform/organizations/${encodeURIComponent(item.id)}/subscription`, { method: 'PATCH', body: JSON.stringify({ plan: select.value }) }); await load(); } catch (error) { select.value = previous; state.loadError = `Не удалось изменить тариф: ${error.message}`; alert(state.loadError); } finally { select.disabled = false; } });
  $('#close-company-detail').addEventListener('click', () => toggleDetail(false)); $('#cancel-company-detail').addEventListener('click', () => toggleDetail(false));
  $('#save-company-detail').addEventListener('click', async (event) => { if (!detailOrgId || !detailLoaded) return; const button = event.currentTarget; const error = $('#company-detail-error'); error.textContent = ''; setBusy(button, true, 'Сохранение…'); try { await api(`/api/platform/organizations/${encodeURIComponent(detailOrgId)}/subscription`, { method: 'PATCH', body: JSON.stringify({ plan: $('#company-detail-plan').value, status: $('#company-detail-status').value }) }); toggleDetail(false); await load(); } catch (e) { error.textContent = `Не удалось сохранить изменения: ${e.message}`; } finally { if (!detailModal.hidden) { button.disabled = !detailLoaded; button.textContent = button.dataset.idleLabel || 'Сохранить'; } } });
  document.addEventListener('keydown', (event) => { if (event.key !== 'Escape') return; if (!modal.hidden) toggleModal(false); if (!detailModal.hidden) toggleDetail(false); });
  $('#platform-logout').addEventListener('click', async (event) => { const button = event.currentTarget; setBusy(button, true, 'Выход…'); try { await api('/api/logout', { method: 'POST' }); location.href = '/login'; } catch (error) { alert(`Не удалось выйти: ${error.message}`); button.disabled = false; button.textContent = button.dataset.idleLabel || 'Выйти'; } });
  $('#organization-form').addEventListener('submit', async (event) => { event.preventDefault(); const formElement = event.currentTarget; if (formElement.dataset.submitting === 'true') return; const submit = formElement.querySelector('[type=submit]'); const form = new FormData(formElement); const error = $('#company-error'); error.textContent = ''; const payload = Object.fromEntries(form.entries()); formElement.dataset.submitting = 'true'; formElement.setAttribute('aria-busy', 'true'); setBusy(submit, true, 'Создание…'); try { await api('/api/platform/organizations', { method: 'POST', body: JSON.stringify(payload) }); toggleModal(false); formElement.reset(); await load(); } catch (e) { error.textContent = e.message === 'slug_or_owner_login_already_exists' ? 'Такой адрес компании или почта владельца уже заняты.' : e.message === 'valid_owner_credentials_required' ? 'Проверьте имя, рабочую почту и пароль владельца.' : e.message === 'invalid_organization_timezone' ? 'Не удалось определить часовой пояс.' : 'Не удалось создать компанию. Проверьте данные и повторите попытку.'; } finally { formElement.dataset.submitting = 'false'; formElement.removeAttribute('aria-busy'); submit.disabled = false; submit.textContent = submit.dataset.idleLabel || 'Создать организацию'; } });
  load();
})();
